	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var InputDone bool = false

var amtFile *os.File
var amtScanner *bufio.Scanner
var currentRec AmtRec

func storePic9V99(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale
	v := value.Truncate(scale)
	// Check if fits: max = 10^intDigits - 10^-scale
	// For overflow, keep low-order digits: modulo 10^intDigits
	// Need to handle positive only; negative not expected here
	// Compute integer representation: v * 10^scale
	factor := decimal.New(1, scale)
	// factor = 10^scale
	intVal := v.Mul(factor)
	// intVal is integer (scale 0)
	modulus := decimal.New(1, int32(intDigits+int(scale)))
	// modulus = 10^(intDigits+scale)
	// For PIC 9(5)V99: intDigits=5 scale=2 => modulus=10^7 =10000000
	// Keep low-order digits: intVal mod modulus (for positive)
	// Use DivMod? Simple using IntPart may overflow int64, use decimal mod
	// decimal doesn't have mod for large, implement via Truncate division
	if intVal.IsNegative() {
		// For completeness: truncate and mod
		// We'll do similar but keep sign?
		// High-order digits dropped: for negative, also low-order?
		// Not needed
	} else {
		if intVal.GreaterThanOrEqual(modulus) || intVal.GreaterThanOrEqual(decimal.New(1, int32(intDigits)).Mul(factor)) {
			// Actually overflow if intDigits part >=10^intDigits
			// But spec says keep low-order digits: mod modulus
			remainder := intVal.Mod(modulus)
			v = remainder.Div(factor)
		}
	}
	// Ensure scale exactly scale? Keep as decimal with correct exponent
	v = v.Truncate(scale)
	return v
}

func storePic(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	return storePic9V99(value, intDigits, scale)
}

func maxForPic(intDigits int, scale int32) decimal.Decimal {
	// max = (10^intDigits -1) + (10^scale -1)/10^scale
	// = 10^intDigits - 10^-scale
	tenPowInt := decimal.New(1, int32(intDigits))
	tenPowMinusScale := decimal.New(1, -scale)
	return tenPowInt.Sub(tenPowMinusScale)
}

func formatEdited(value decimal.Decimal, pic string) string {
	// Support ZZ,ZZ9.99 and ZZ,ZZ9.9
	// Determine integer width, scale, comma positions
	// Parse pic
	var intPartPic string
	var fracPartPic string
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPartPic = pic[:idx]
		fracPartPic = pic[idx+1:]
	} else {
		intPartPic = pic
		fracPartPic = ""
	}
	scale := len(fracPartPic)
	intWidth := len(intPartPic) // includes commas

	// Prepare truncated absolute value with exactly scale fractional digits
	// Value may be negative? Not expected
	sign := ""
	if value.IsNegative() {
		sign = "-"
		value = value.Neg()
	}
	// Truncate to scale (COBOL storage already truncated)
	value = value.Truncate(int32(scale))

	// For formatting overflow: if integer digits exceed number of digit placeholders, drop high-order digits.
	// Count digit placeholders: Z and 9 in intPartPic
	digitPlaceholders := 0
	for _, c := range intPartPic {
		if c == 'Z' || c == '9' {
			digitPlaceholders++
		}
	}
	// Get integer part as string
	factor := decimal.New(1, int32(scale))
	intVal := value.Mul(factor).Truncate(0)
	// intVal = overall integer representation
	// split into integer and fractional via string
	// Instead format with scale digits
	// Use decimal StringFixed? We'll build manually
	// Get integer digits of original integer part: value integer = floor(value)
	intPartVal := value.Truncate(0)
	fracPartVal := value.Sub(intPartVal)

	// For overflow detection, need integer digit count vs placeholders
	// If integer part has more digits than placeholders, keep low-order digits
	intStrRaw := intPartVal.StringFixed(0) // no exponent
	// Remove sign
	if strings.HasPrefix(intStrRaw, "-") {
		intStrRaw = intStrRaw[1:]
	}
	if len(intStrRaw) > digitPlaceholders {
		intStrRaw = intStrRaw[len(intStrRaw)-digitPlaceholders:]
	}
	// Now format intPartPic with intStrRaw
	// intPartPic length = intWidth, contains commas and Zs/9s
	// We need to map digit placeholders positions to digits of intStrRaw right-aligned
	// Collect placeholder positions
	type pos struct {
		idx  int
		kind byte // Z or 9
	}
	var ph []pos
	for i, c := range intPartPic {
		if c == 'Z' || c == '9' {
			ph = append(ph, pos{i, byte(c)})
		}
	}
	// Digits for integer part to place: intStrRaw, right-aligned in ph
	// pad left with zeros
	digits := []byte(strings.Repeat("0", digitPlaceholders-len(intStrRaw)) + intStrRaw)

	// Build formatted integer part char array
	outInt := []byte(intPartPic) // will replace placeholders
	for i, p := range ph {
		outInt[p.idx] = digits[i]
	}
	// Now apply Z suppression: leading zeros in Z zone become spaces, and commas inside suppressed zone become spaces
	// Z zone is from start until last Z? Actually any Z placeholder that is zero and no non-zero digit to its left remains suppressed.
	// Simpler: scan ph in order, keep flag suppress=true until we encounter a non-zero digit or we are at a 9 placeholder.
	// When suppressing, set that placeholder char to space.
	// After suppression ends, remaining placeholders stay as digits (including zeros).
	suppress := true
	for _, p := range ph {
		c := outInt[p.idx]
		if p.kind == '9' {
			// 9 always prints, and suppression ends before it
			suppress = false
			break
		}
		if c != '0' {
			suppress = false
			break
		}
		// c == '0' and Z
		if suppress {
			// check if there is any non-zero later? Actually we suppress this zero
			// We'll mark for now; need to know if all remaining Zs are zero -> they stay suppressed except last 9 zone
			// So continue
		} else {
			break
		}
	}
	if suppress {
		// Need to handle case where all Z digits are zero: they remain blank
		// Determine last index where suppression applies: all Z placeholders that are leading zeros
		// If value integer part is zero, then all Z's are zero, suppression covers all Z's
		// For ZZ,ZZ9 case: integer zero => should be "      0" style (only 9 prints 0)
	}
	// Apply suppression iteratively
	suppress = true
	for _, p := range ph {
		if !suppress {
			break
		}
		if p.kind == '9' {
			suppress = false
			break
		}
		if outInt[p.idx] != '0' {
			suppress = false
			break
		}
		outInt[p.idx] = ' '
	}
	// After Z suppression, commas that have only spaces to the left become spaces
	// Find first non-space character in outInt
	firstNonSpace := -1
	for i, c := range outInt {
		if c != ' ' && c != ',' {
			firstNonSpace = i
			break
		}
		if c == ',' {
			continue
		}
	}
	// Actually commas themselves may be leading
	// Rule: commas inside suppressed zone become spaces
	// Implement: iterate outInt left to right; if we are still in suppressed zone (no digit printed yet), commas become space
	seenDigit := false
	// Determine seenDigit as encountering a digit character (0-9) that is not suppressed
	// We have already replaced suppressed Zs with spaces.
	// Now scan:
	for i, c := range outInt {
		if c == ',' {
			if !seenDigit {
				// check if any digit to the right is non-space? If remaining integer part is all spaces before 9, this comma is in suppressed zone
				// Look ahead for a digit
				hasDigitAhead := false
				for j := i + 1; j < len(outInt); j++ {
					if outInt[j] >= '0' && outInt[j] <= '9' {
						hasDigitAhead = true
						break
					}
				}
				if !hasDigitAhead {
					// No digit ahead? Should remain? For ZZ,ZZ9.99 comma after suppression should be space
				}
				// Simpler: if not yet seenDigit, comma becomes space
				outInt[i] = ' '
			}
		} else if c >= '0' && c <= '9' {
			// If this is a real digit: if it's 0 but part of suppressed? Already turned to space
			// But if c is digit, we have seen a digit only if not space
			// However leading spaces are not digits
			// For case where integer is 0, the 9 placeholder prints 0, so that counts
			seenDigit = true
		} else if c == ' ' {
			// keep
		}
		_ = firstNonSpace
	}

	intFormatted := string(outInt)

	// Fractional part
	fracFormatted := ""
	if scale > 0 {
		// Build fractional string with exactly scale digits, truncated
		// frac = (value - intPartVal) *10^scale
		fracInt := fracPartVal.Mul(factor).Truncate(0).Abs()
		fracStr := fracInt.StringFixed(0)
		// pad left zeros to scale
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
		fracFormatted = "." + fracStr
		intFormatted = intFormatted + fracFormatted
	}

	// Apply sign if needed: place at leftmost? For simplicity prepend
	if sign != "" {
		// In COBOL PIC without S, sign not shown; ignore
	}

	return intFormatted
}

func parseArAmt(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// s contains 7 digits, implied V99: last 2 digits fractional
	n := decimal.RequireFromString(s)
	return decimal.New(n.IntPart(), -2)
}

func main() {
	// Open input.dat
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	amtFile = f
	amtScanner = bufio.NewScanner(f)

