		amtFile.Close()
	}
}

func READPARA() {
	if amtScanner.Scan() {
		line := amtScanner.Text()
		// Pad to 11
		if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		arAcct := line[0:4]
		arAmtStr := line[4:11]
		currentRec.ArAcct = arAcct
		currentRec.ArAmt = parseArAmt(arAmtStr)
