	maxVal := maxForPic(5, 2)
	if candidateTrunc.GreaterThan(maxVal) {
		OVERFLOWPARA()
		// target unchanged, and ADD 1 TO WS-COUNT etc still execute?
		// According to note, ON SIZE ERROR action is out-of-line PERFORM. A nested ADD ... END-ADD there is ambiguous and silently changes which statements belong to the SIZE ERROR branch.
		// The COBOL has:
